head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL01030";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil01030.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_txtisurCdVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_txtfssUnqNoVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_txtcomNmVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_findDesignAdvser_onclick
 * @description 지정자문인 신고회사 조회 버튼 클릭 — 지정자문인 조회 팝업(JLDFIL01040)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_findDesignAdvser_onclick = async function(e){
    try {
        await scwin.findCompanyDesignAdvser()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01030.btn_findDesignAdvser_onclick' }); }
};

/**
 * @method
 * @name btn_findCompany_onclick
 * @description 대상회사 조회 버튼 클릭 — 코넥스 상장회사 조회 팝업(JLDFIL00033)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_findCompany_onclick = async function(e){
    try {
        await scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01030.btn_findCompany_onclick' }); }
};

/**
 * @method
 * @name btn_goWrite_onclick
 * @description 문서작성 버튼 클릭 — 공시 등록 후 작성 단계로 진행
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWrite_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil01030.btn_goWrite_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_documentWrite
 * @description document Write 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_documentWrite = async function (action) {
    const sbmOptions = {
        id: "tx_documentWrite",
        method: "post",
        action: action ?? "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goWrite
 * @description go Write 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goWrite = async function (action) {
    const sbmOptions = {
        id: "tx_goWrite",
        method: "post",
        action: action ?? "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL1 = '/ui/jsp/JLDFIL00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup(corpSearchURL1, { id: "konexCorpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, { method: "loadInitPage", ldMktTpCd: "6" }));
};

/**
 * @method
 * @name findCompanyDesignAdvser
 * @description find Company Design Advser 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompanyDesignAdvser = async function () {
    const corpSearchURL2 = '/ui/jsp/JLDFIL01040.xml';
    await $c.win.openPopup(corpSearchURL2, { id: "designAdvserWin", scrollbars: false, resizable: false, width: "600", height: "550", type: "pageFramePopup" }, { method: "loadInitPageForDesignAdvser" });
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} comEngAbbrv comEngAbbrv
 * @param {*} returnKey returnKey
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, comEngAbbrv, returnKey) {
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comAbbrv);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('chkPop', 'Y');
};

/**
 * @method
 * @name setCorpInfoDesignAdvser
 * @description set Corp Info Design Advser 처리
 * @param {String} isurCd isurCd
 * @param {*} fssUnqNo fssUnqNo
 * @param {String} comNm comNm
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfoDesignAdvser = function (isurCd, fssUnqNo, comNm, repIsuSrtCd) {
    $c.util.getComponent("ipt_txtisurCdVote").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNoVote").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNmVote").setValue(comNm);
    $c.util.getComponent('dma_documentWriteReq').set('chkPop', 'Y');
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    await scwin.tx_documentWrite('/submission/disclosure.do?method=searchDisclosureDocument');
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '' || $c.util.getComponent('dma_documentWriteReq').get('chkPop') === '') {
        if (await $c.win.confirm('대상회사를 선택하지 않으시면 대상회사가 없는 공시로 제출됩니다. \n계속하시겠습니까?')) {
            $c.util.getComponent('dma_documentWriteReq').set('tgtComNmVote', $c.util.getComponent('ipt_txtcomNmVote').getValue());
            $c.util.getComponent('dma_documentWriteReq').set('tgtComNmVote', $c.util.getComponent('ipt_txtcomNmVote').getValue());
            $c.util.getComponent('dma_documentWriteReq').set('isurCd', $c.util.getComponent('ipt_txtisurCdVote').getValue());
            $c.util.getComponent('dma_documentWriteReq').set('fssUnqNo', $c.util.getComponent('ipt_txtfssUnqNoVote').getValue());
        } else {
            return;
        }
    } else {
        $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtComNmVote', $c.util.getComponent('ipt_txtcomNmVote').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('tgtComNmVote', $c.util.getComponent('ipt_txtcomNmVote').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('isurCd', $c.util.getComponent('ipt_txtisurCdVote').getValue());
        $c.util.getComponent('dma_documentWriteReq').set('fssUnqNo', $c.util.getComponent('ipt_txtfssUnqNoVote').getValue());
    }
    await scwin.tx_goWrite('/submission/disclosurereg.do?method=registerDisclosure');
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
